int predict_random_forest(const float *features) {
    float class_probabilities[8] = {0.0f};
    int n_estimators = 200;
    int n_classes = 8;

    for (int i = 0; i < n_estimators; i++) {
        int node = 0;
        while (RF_FEAT[i][node] != -2) {
            int feat_idx = RF_FEAT[i][node];
            if (features[feat_idx] <= RF_THRESH[i][node]) {
                node = RF_LEFT[i][node];
            } else {
                node = RF_RIGHT[i][node];
            }
        }
        int prob_offset = node * n_classes;
        for (int c = 0; c < n_classes; c++) {
            class_probabilities[c] += RF_PROBS[i][prob_offset + c];
        }
    }

    int best_class = 0;
    float max_prob = class_probabilities[0];
    for (int c = 1; c < n_classes; c++) {
        if (class_probabilities[c] > max_prob) {
            max_prob = class_probabilities[c];
            best_class = c;
        }
    }
    return best_class;
}
